    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Structural norms and degeneracy annihilation", H("Structural norms and degeneracy annihilation"), Blocks(
        Paragraph(Text("An operator is a norm when it is generated by a diagonal noninjective simplex operator with an arbitrary remaining operator, and is closed under zero, addition and negation. This is a structural predicate on finite integer combinations of letters, in all natural degrees. Priming preserves norms.")),
        Paragraph(Text("For any abelian category C with independent object and morphism universes and any bisimplicial X, realizing a norm and then applying diagonal Moore retraction gives zero. Each first-direction or second-direction degenerate input to the shuffle map becomes diagonally degenerate. Therefore the diagonal projector PInfty makes the shuffle insensitive to the two-direction normalization projector. These are the degeneracy facts required for both normalized composites.")),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-isnorm-b0be79"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.IsNorm"), H("IsNorm"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Structural norm class for diagonal degeneracies, closed under `+` and `neg`. The point of this definition is that closure under `prime` is formal, so the induction can be run before realizing operators on a bisimplicial object.")), Paragraph(Text("In this notation, inductive IsNorm : {s q : ℕ} → DerivedOp s q → Prop."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-prime-single-diag-a15d2c"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.prime_single_diag"), H("prime_single_diag"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`prime` of a diagonal letter `⟨θ,θ⟩` is the diagonal of `primeHom θ`.")), Paragraph(Text("In this notation, lemma prime_single_diag {s q : ℕ} (θ : (⦋q⦌ : SimplexCategory) ⟶ ⦋s⦌) : DerivedOp.prime (Finsupp.single (⟨θ, θ⟩ : OpLetter s q) 1) = Finsupp.single (⟨primeHom θ, primeHom θ⟩ : OpLetter (s + 1) (q + 1)) 1."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-primehom-not-mono-2ca0cf"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.primeHom_not_mono"), H("primeHom_not_mono"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`primeHom` preserves non-monicity: `primeHom θ` is injective iff `θ` is, and `Mono` in `SimplexCategory` is injectivity.")), Paragraph(Text("In this notation, lemma primeHom_not_mono {s q : ℕ} {θ : (⦋q⦌ : SimplexCategory) ⟶ ⦋s⦌} (hθ : ¬ Mono θ) : ¬ Mono (primeHom θ)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-primehom-id-2d0133"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.primeHom_id"), H("primeHom_id"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`prime` fixes the identity map: `primeHom 𝟙 = 𝟙` (`0 ↦ 0`, `j+1 ↦ 𝟙(j)+1 = j+1`).")), Paragraph(Text("In this notation, lemma primeHom_id (q : ℕ) : primeHom (𝟙 (⦋q⦌ : SimplexCategory)) = 𝟙 _."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-prime-idop-f0b904"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.prime_idOp"), H("prime_idOp"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`i' = i` (md 173–175, implicit in priming the IH's `−c_q`): the derived operator of the identity is the identity.")), Paragraph(Text("In this notation, lemma prime_idOp (q : ℕ) : (idOp q).prime = idOp (q + 1)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-lastface-comp-d0-8d57a0"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.lastFace_comp_D0"), H("lastFace_comp_D0"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("**`F₀ D₀ = i`** (`δ_0 ≫ σ_0 = 𝟙`): the last face undoes the 0-th degeneracy. Repackages the existing `face_zero_comp_D0` (`lastFaceOp = faceOp _ 0`).")), Paragraph(Text("In this notation, lemma lastFace_comp_D0 (q : ℕ) : (lastFaceOp (q + 1)).comp (D0op (q + 1)) = idOp (q + 1)."))), DescribeRole.Theorem),
