        Describe.Lean(DescribeId.Create("ez-normalizedoperators-lastface-comp-hprime-comp-d0-6909e8"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.lastFace_comp_hPrime_comp_D0"), H("lastFace_comp_hPrime_comp_D0"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("**`F₀ h' D₀ = h` (EM line 192).** `F₀ h' D₀ = (h F₀) D₀ = h (F₀ D₀) = h`, using `lastFace_comp_hPrime` and `F₀ D₀ = i` (`δ_0 ≫ σ_0 = 𝟙`).")), Paragraph(Text("In this notation, lemma lastFace_comp_hPrime_comp_D0 (q : ℕ) : (lastFaceOp (q + 1)).comp (((hOp (q + 1)).prime).comp (D0op (q + 1))) = hOp (q + 1)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-diagpinfty-a61187"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.diagPInfty"), H("diagPInfty"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("`PInfty` of the diagonal in degree `n`, typed on the `(n, n)` entry of `X`.")), Paragraph(Text("In this notation, noncomputable def diagPInfty (X : BisimplicialObject C) (n : ℕ) : (X.obj (Opposite.op ⦋n⦌)).obj (Opposite.op ⦋n⦌) ⟶ (X.obj (Opposite.op ⦋n⦌)).obj (Opposite.op ⦋n⦌)."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-ezcomponent-inner-degeneracy-comp-pinfty-59f7e8"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.ezComponent_inner_degeneracy_comp_PInfty"), H("ezComponent_inner_degeneracy_comp_PInfty"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("**EZ–degeneracy kill, inner (vertical) direction (the per-summand combinatorial core).** A `(p, m+1)`-shuffle component of a chain that is *degenerate in the inner simplicial direction* (in the image of the inner degeneracy `s_i = (X_⦋p⦌).map (σ i).op : X_{p,m} → X_{p,m+1}`) is sent by the Eilenberg–Zilber component to a *diagonally* degenerate chain, hence annihilated by `PInfty`. EM Lemma I.5.3 content: `∇ ∘ (1 ⊗ s_i) = s_? ∘ ∇'` lands in a diagonal degeneracy.")), Paragraph(Text("In this notation, lemma ezComponent_inner_degeneracy_comp_PInfty (X : BisimplicialObject C) (p m : ℕ) (i : Fin (m + 1)) : (X.obj (Opposite.op ⦋p⦌)).map (SimplexCategory.σ i).op ≫ ezComponent X p (m + 1) ≫ diagPInfty X (p + (m + 1)) = 0."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-ezcomponent-outer-degeneracy-comp-pinfty-398cc8"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.ezComponent_outer_degeneracy_comp_PInfty"), H("ezComponent_outer_degeneracy_comp_PInfty"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("**EZ–degeneracy kill, outer (horizontal) direction (the per-summand combinatorial core).** An `(a+1, q)`-shuffle component of a chain that is *degenerate in the outer simplicial direction* (in the image of the outer degeneracy `s_i = (X.map (σ i).op).app ⦋q⦌ : X_{a,q} → X_{a+1,q}`) is sent by the Eilenberg–Zilber component to a *diagonally* degenerate chain, hence annihilated by `PInfty`. EM Lemma I.5.3 content: `∇ ∘ (s_i ⊗ 1) = s_? ∘ ∇'` lands in a diagonal degeneracy.")), Paragraph(Text("In this notation, lemma ezComponent_outer_degeneracy_comp_PInfty (X : BisimplicialObject C) (a q : ℕ) (i : Fin (a + 1)) : (X.map (SimplexCategory.σ i).op).app (Opposite.op ⦋q⦌) ≫ ezComponent X (a + 1) q ≫ diagPInfty X (a + 1 + q) = 0."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-degenerate-shufflemap-comp-pinfty-9525dc"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.degenerate_shuffleMap_comp_PInfty"), H("degenerate_shuffleMap_comp_PInfty"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The degenerate part of `FOne` is sent by `shuffleMap` to a diagonal degeneracy, hence is killed by `PInfty`. Concretely, after decomposing the complementary projector `𝟙 - retractionNOne ≫ inclusionNOne` bidegreewise, the resulting inner- and outer-degenerate pieces are annihilated by `ezComponent_inner_degeneracy_comp_PInfty` and `ezComponent_outer_degeneracy_comp_PInfty`.")), Paragraph(Text("In this notation, lemma degenerate_shuffleMap_comp_PInfty (X : BisimplicialObject C) : (𝟙 (FOne.obj X) - retractionNOne X ≫ inclusionNOne X) ≫ shuffleMap X ≫ (PInfty : FTwo.obj X ⟶ FTwo.obj X) = 0."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-0c43075066bc"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.retractionNOne_inclusionNOne_shuffleMap_PInfty"), H("retractionNOne_inclusionNOne_shuffleMap_PInfty"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The round trip `retractionNOne ≫ inclusionNOne` is absorbed under `shuffleMap ≫ PInfty`. The correction term `1 - retractionNOne ≫ inclusionNOne` lands in the degenerate part of the diagonal, which `PInfty` kills.")), Paragraph(Text("In this notation, @[reassoc] lemma retractionNOne_inclusionNOne_shuffleMap_PInfty (X : BisimplicialObject C) : retractionNOne X ≫ inclusionNOne X ≫ shuffleMap X ≫ (PInfty : FTwo.obj X ⟶ FTwo.obj X) = shuffleMap X ≫ PInfty."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-isnorm-kill-e59ca2"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.kill"), H("IsNorm.kill"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("**Every norm dies under `retractionNTwo`** (for every `X`). Structural induction: linear cases are `realize`-linearity; the structural generator is a diagonal degeneracy composed with an operator.")), Paragraph(Text("In this notation, lemma IsNorm.kill {s q : ℕ} {M : DerivedOp s q} (h : IsNorm M) (X : BisimplicialObject C) : DerivedOp.realize X M ≫ (retractionNTwo X).f q = 0."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-isnorm-prime-827aa0"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.prime"), H("IsNorm.prime"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The structural norm class is closed under `prime`.")), Paragraph(Text("In this notation, lemma IsNorm.prime {s q : ℕ} {M : DerivedOp s q} (h : IsNorm M) : IsNorm M.prime."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-factor-through-sigma"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.factor_through_\u03c3"), H("factor_through_\u03c3"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("For every n : Nat, Δ : SimplexCategory, a : Fin(n+1) and f : [n+1] → Δ, if f.toOrderHom a.castSucc = f.toOrderHom a.succ, then f = σ a ≫ δ a.castSucc ≫ f. The common adjacent value makes the codegeneracy factorization exact."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("ez-normalizedoperators-sigma-not-mono"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/NormalizedOperators.sigma_not_mono"), H("sigma_not_mono"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("For every n : Nat and a : Fin(n+1), ¬ Mono (SimplexCategory.σ a). Its two distinct adjacent vertices have the same image."))), DescribeRole.Theorem))));
